import type { Metadata } from 'next'
import { Inter } from 'next/font/google'
import Link from 'next/link'
import { AppProvider } from '@/components/AppProvider'
import '@/styles/globals.css'

const inter = Inter({
  subsets: ['latin'],
  display: 'swap',
})

export const metadata: Metadata = {
  title: {
    default: 'My Blog',
    template: '%s - My Blog',
  },
  description: 'A complex blog application',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en" className={inter.className}>
      <body>
        <AppProvider>
          <div className="app-container">
            <header>
              <h1>My Blog</h1>
              <nav>
                <Link href="/">Home</Link>
                <Link href="/blog">Blog</Link>
              </nav>
            </header>
            <main>{children}</main>
            <footer>
              <p>&copy; 2024 My Blog</p>
            </footer>
          </div>
        </AppProvider>
      </body>
    </html>
  )
}

import Link from 'next/link'
import { headers } from 'next/headers'
import type { Metadata } from 'next'
import { NavigateButton } from '@/components/NavigateButton'

type Post = {
  id: number
  title: string
}

export const metadata: Metadata = {
  title: 'Home',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

async function getPosts(): Promise<Post[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  )
  return res.json()
}

export default async function HomePage() {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || ''
  const posts = await getPosts()
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <NavigateButton href="/blog">View All Posts</NavigateButton>
    </div>
  )
}

import Link from 'next/link'
import type { Metadata } from 'next'
import { NavigateButton } from '@/components/NavigateButton'

type Post = {
  id: number
  title: string
  body: string
}

export const metadata: Metadata = {
  title: 'Blog',
  description: 'All blog posts',
}

async function getPosts(): Promise<Post[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts', {
    next: { revalidate: 60 },
  })
  return res.json()
}

export default async function BlogIndex() {
  const posts = await getPosts()

  return (
    <div>
      <h1>All Blog Posts</h1>

      <div className="posts-grid">
        {posts.map((post) => (
          <div key={post.id} className="post-card">
            <h2>
              <Link href={`/blog/${post.id}`}>{post.title}</Link>
            </h2>
            <p>{post.body.substring(0, 100)}...</p>
            <NavigateButton href={`/blog/${post.id}`}>
              Read More
            </NavigateButton>
          </div>
        ))}
      </div>
    </div>
  )
}

import { notFound } from 'next/navigation'
import type { Metadata } from 'next'
import { BackButton } from '@/components/BackButton'

type Post = {
  id: number
  title: string
  body: string
}

type Comment = {
  id: number
  name: string
  body: string
  email: string
}

type PostWithComments = {
  post: Post
  comments: Comment[]
}

async function getPostAndComments(id: string): Promise<PostWithComments | null> {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])

    if (!postRes.ok) {
      return null
    }

    const post = (await postRes.json()) as Post
    const comments = (await commentsRes.json()) as Comment[]

    return { post, comments }
  } catch {
    return null
  }
}

export async function generateStaticParams() {
  const posts = (await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())) as { id: number }[]

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export const dynamicParams = true

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>
}): Promise<Metadata> {
  const { id } = await params
  const result = await getPostAndComments(id)

  if (!result) {
    return { title: 'Post Not Found' }
  }

  const { post } = result

  return {
    title: post.title,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  }
}

export default async function BlogPost({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params
  const result = await getPostAndComments(id)

  if (!result) {
    notFound()
  }

  const { post, comments } = result

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import { NextRequest, NextResponse } from 'next/server'

type Post = {
  id: number
  title: string
  content: string
}

type NewPostInput = {
  title: string
  content: string
}

type NewPost = {
  id: number
  title: string
  content: string
  createdAt: string
}

export async function GET() {
  const posts: Post[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts)
}

export async function POST(request: NextRequest) {
  const body = (await request.json()) as NewPostInput
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: NewPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

